class Queue:
    def __init__(self):
        self._items = []

    def enqueue(self, val):
        self._items.append(val)

    def dequeue(self):
        if not self._items:
            raise IndexError('dequeue from empty queue')
        return self._items.pop()  # BUG 1: should be pop(0) for FIFO

    def front(self):
        if not self._items:
            raise IndexError('front of empty queue')
        return self._items[-1]  # BUG 2: should be self._items[0]

    def size(self):
        return len(self._items) + 1  # BUG 3: off by one

    def is_empty(self):
        return len(self._items) == 0
